1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible animated circle with hover effects">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      --bg: #fff;
19	      --fg: #2563eb;
20	      --shadow: rgba(0, 0, 0, 0.1);
21	    }
22	    @media (prefers-color-scheme: dark) {
23	      :root {
24	        --bg: #111;
25	        --fg: #60a5fa;
26	        --shadow: rgba(0, 0, 0, 0.6);
27	      }
28	    }
29	    @media (prefers-contrast: more) {
30	      :root {
31	        --shadow: rgba(0, 0, 0, 0.9);
32	      }
33	    }
34	    .hint {
35	      margin-top: 1.5rem;
36	      font-size: 0.875rem;
37	      text-align: center;
38	      opacity: 0.7;
39	    }
40	    body {
41	      min-height: 100dvh;
42	      display: grid;
43	      place-items: center;
44	      padding: 1rem;
45	      background: var(--bg);
46	      color: var(--fg);
47	      font-family: system-ui, -apple-system, sans-serif;
48	    }
49	    main {
50	      width: 100%;
51	      display: flex;
52	      justify-content: center;
53	    }
54	    svg {
55	      display: block;
56	      width: min(400px, 100%);
57	      height: auto;
58	      overflow: visible;
59	      filter: drop-shadow(0 8px 16px var(--shadow));
60	    }
61	    circle {
62	      transition: opacity 0.3s ease;
63	      transform-box: fill-box;
64	      transform-origin: center;
65	      opacity: 0.9;
66	    }
67	    svg:focus {
68	      outline: none;
69	    }
70	    svg:focus-visible {
71	      outline: 3px solid var(--fg);
72	      outline-offset: 8px;
73	      border-radius: 50%;
74	    }
75	    @media (hover: hover) {
76	      circle:hover {
77	        opacity: 1;
78	      }
79	    }
80	    circle:active,
81	    svg:focus-visible circle {
82	      opacity: 1;
83	    }
84	    @media (prefers-reduced-motion: no-preference) {
85	      circle {
86	        transition:
87	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
88	          opacity 0.3s ease;
89	      }
90	      circle:active,
91	      svg:focus-visible circle {
92	        transform: scale(1.05);
93	      }
94	    }
95	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
96	      circle:hover {
97	        transform: scale(1.05);
98	      }
99	    }
100	  </style>
101	</head>
102	<body>
103	  <main>
104	    <div>
105	      <svg viewBox="0 0 400 400" role="button" aria-labelledby="circle-title" tabindex="0" xmlns="http://www.w3.org/2000/svg">
106	        <title id="circle-title">Colored circle. Click or press Enter/Space to change its color. Grows slightly on hover or focus.</title>
107	        <circle cx="200" cy="200" r="180" fill="currentColor"/>
108	      </svg>
109	      <p class="hint">Click or press Enter/Space to change the color</p>
110	    </div>
111	  </main>
112	  <script>
113	    const svg = document.querySelector('svg');
114	    const colors = ['#2563eb', '#dc2626', '#16a34a', '#d97706', '#7c3aed', '#0891b2'];
115	    let index = 0;
116	
117	    function cycleColor() {
118	      index = (index + 1) % colors.length;
119	      svg.style.color = colors[index];
120	    }
121	
122	    svg.addEventListener('click', cycleColor);
123	    svg.addEventListener('keydown', (e) => {
124	      if (e.key === 'Enter' || e.key === ' ') {
125	        e.preventDefault();
126	        cycleColor();
127	      }
128	    });
129	  </script>
130	</body>
131	</html>
